describe('Accessible Product Images and Login Fields', () => {
  it('should have accessible login fields with placeholders', () => {
    cy.visit('https://www.saucedemo.com');
    cy.get('[data-test="username"]').should('have.attr', 'placeholder');
    cy.get('[data-test="password"]').should('have.attr', 'placeholder');
  });

  it('should not change the URL after logging in', () => {
    cy.visit('https://www.saucedemo.com');
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="loginButton"]').click();
    cy.url().should('eq', 'https://www.saucedemo.com');
  });
});
